const { ForbiddenException } = require('@nestjs/common');
const { RoleGuard } = require('./guards/role.guard');

// Define your roles here
const ROLES = {
  ADMIN: 'admin',
  USER: 'user',
};

/**
 * @description Create an application with role-based access control.
 */
async function createApp() {
  const app = await NestFactory.create(AppModule);

  // Configure typeorm connection
  const ormConfig = {
    type: process.env.DB_TYPE || 'sqlite',
    database: process.env.DB_NAME || ':memory:',
    synchronize: true,
    logging: false,
    entities: [__dirname + '/../**/*.entity{.ts,.js}'],
    migrations: [__dirname + '/../migrations/*{.ts,.js}'],
  };

  if (process.env.DB_TYPE === 'mysql') {
    ormConfig.type = 'mysql';
  }

  if (process.env.DB_TYPE === 'postgres') {
    ormConfig.type = 'postgres';
    ormConfig.host = process.env.DB_HOST;
    ormConfig.username = process.env.DB_USERNAME;
    ormConfig.password = process.env.DB_PASSWORD;
    ormConfig.database = process.env.DB_NAME;
  }

  await TypeOrm.init(ormConfig);
  app.useStaticAssets('public');
  app.setBasePublicPath('/public');
  app.apply(LoggerMiddleware());
  app.enableCors();

  // Apply the role guard to all routes
  app.useGlobalGuards(new RoleGuard());

  app.listen(process.env.PORT || 3000, () =>
    console.log(`Server is running on port ${process.env.PORT || 3000}`),
  );
}

createApp();
```

This example creates a simple Express app using NestJS's `NestFactory` to boot up the server. It uses TypeScript for its typescript definitions (`typeorm`). The app listens at port 3000 unless it has been configured otherwise.

The role guard is applied globally to all incoming requests. The guard checks if the user has the required role before allowing access to the requested route.

